use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};
use serde::{Deserialize, Serialize};

use crate::index::backlink_index::{BacklinkIndex, BacklinkResult};
use crate::index::metadata_extractor::extract_metadata;
use crate::index::metadata_index::MetadataIndex;
use crate::index::workspace_scanner::WorkspaceScanner;

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub struct ReindexReport {
    pub indexed: usize,
    pub skipped: usize,
    pub errors: Vec<String>,
}

#[derive(Clone)]
pub struct ReindexEngine {
    pub index: Arc<Mutex<MetadataIndex>>,
    pub backlinks: Arc<Mutex<BacklinkIndex>>,
    pub root: PathBuf,
}

impl ReindexEngine {
    pub fn new(root: PathBuf) -> Self {
        Self {
            index: Arc::new(Mutex::new(MetadataIndex::new())),
            backlinks: Arc::new(Mutex::new(BacklinkIndex::new())),
            root,
        }
    }

    pub fn with_index(root: PathBuf, index: Arc<Mutex<MetadataIndex>>) -> Self {
        Self {
            index,
            backlinks: Arc::new(Mutex::new(BacklinkIndex::new())),
            root,
        }
    }

    /// Executa uma varredura e reindexação completa do workspace.
    pub fn full_reindex(&self) -> Result<ReindexReport, String> {
        let scanner = WorkspaceScanner::new(self.root.clone());
        let docs = scanner.scan()?;

        let mut index = self.index.lock().map_err(|e| e.to_string())?;
        *index = MetadataIndex::new();

        let mut report = ReindexReport {
            indexed: 0,
            skipped: 0,
            errors: Vec::new(),
        };

        for doc in docs {
            index.insert(doc);
            report.indexed += 1;
        }

        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0);
        index.indexed_at = now;
        self.rebuild_backlinks_locked(&index);

        Ok(report)
    }

    /// Reindexa um único arquivo de forma incremental (após salvar ou modificação externa).
    pub fn reindex_file(&self, path: &Path) -> Result<(), String> {
        let abs_path = if path.is_absolute() {
            path.to_path_buf()
        } else {
            self.root.join(path)
        };

        // Caminho relativo para armazenamento consistente no índice
        let rel_path = if abs_path.starts_with(&self.root) {
            abs_path
                .strip_prefix(&self.root)
                .map(|p| p.to_path_buf())
                .unwrap_or_else(|_| path.to_path_buf())
        } else {
            path.to_path_buf()
        };

        if !abs_path.exists() {
            return Err(format!("Arquivo não existe: {}", abs_path.display()));
        }

        let mut metadata = extract_metadata(&abs_path)?;
        metadata.path = rel_path.clone();

        let mut index = self.index.lock().map_err(|e| e.to_string())?;
        index.insert(metadata);

        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0);
        index.indexed_at = now;
        // replace_source of this file, then rebuild so other sources re-resolve
        // (e.g. a newly created target turns previous Unresolved links into Resolved).
        self.replace_backlinks_source_locked(&rel_path, &index);
        self.rebuild_backlinks_locked(&index);

        Ok(())
    }

    /// Remove um arquivo do índice (caso tenha sido removido externamente).
    pub fn remove_file(&self, path: &Path) -> Result<bool, String> {
        let rel_path = if path.is_absolute() && path.starts_with(&self.root) {
            path.strip_prefix(&self.root)
                .map(|p| p.to_path_buf())
                .unwrap_or_else(|_| path.to_path_buf())
        } else {
            path.to_path_buf()
        };

        let mut index = self.index.lock().map_err(|e| e.to_string())?;
        let removed = index.remove(&rel_path).is_some();
        if removed {
            self.remove_backlinks_source_locked(&rel_path);
            self.rebuild_backlinks_locked(&index);
        }
        Ok(removed)
    }

    /// Rebuild the reverse index from the current metadata snapshot.
    /// Used after loading a persisted MetadataIndex (backlinks are never persisted).
    pub fn rebuild_backlinks(&self) {
        match self.index.lock() {
            Ok(index) => self.rebuild_backlinks_locked(&index),
            Err(err) => eprintln!("backlink rebuild skipped: {err}"),
        }
    }

    pub fn backlinks_for(&self, target: &Path) -> Result<BacklinkResult, String> {
        let index = self.index.lock().map_err(|e| e.to_string())?;
        let backlinks = self.backlinks.lock().map_err(|e| e.to_string())?;
        Ok(backlinks.backlinks_for(target, &index))
    }

    /// Apply a filesystem watch event to the existing metadata + backlink indexes.
    /// Does not spawn a watcher; callers reuse the single notify hub.
    pub fn apply_external_change(&self, kind: &str, relative_path: &Path, from: Option<&Path>) {
        match kind {
            "removed" => {
                let _ = self.remove_file(relative_path);
            }
            "renamed" => {
                if let Some(from) = from {
                    let _ = self.remove_file(from);
                }
                if is_markdown(relative_path) {
                    let _ = self.reindex_file(relative_path);
                }
            }
            _ => {
                if is_markdown(relative_path) {
                    let _ = self.reindex_file(relative_path);
                }
            }
        }
    }

    fn rebuild_backlinks_locked(&self, index: &MetadataIndex) {
        match self.backlinks.lock() {
            Ok(mut backlinks) => backlinks.rebuild(index),
            Err(err) => eprintln!("backlink rebuild failed: {err}"),
        }
    }

    fn replace_backlinks_source_locked(&self, source: &Path, index: &MetadataIndex) {
        match self.backlinks.lock() {
            Ok(mut backlinks) => backlinks.replace_source(source, index),
            Err(err) => eprintln!(
                "backlink replace_source skipped for {}: {err}",
                source.display()
            ),
        }
    }

    fn remove_backlinks_source_locked(&self, source: &Path) {
        match self.backlinks.lock() {
            Ok(mut backlinks) => backlinks.remove_source(source),
            Err(err) => eprintln!(
                "backlink remove_source skipped for {}: {err}",
                source.display()
            ),
        }
    }
}

fn is_markdown(path: &Path) -> bool {
    path.extension()
        .and_then(|ext| ext.to_str())
        .is_some_and(|ext| ext.eq_ignore_ascii_case("md"))
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use tempfile::TempDir;

    fn write(root: &Path, name: &str, body: &str) {
        if let Some(parent) = root.join(name).parent() {
            let _ = fs::create_dir_all(parent);
        }
        fs::write(root.join(name), body).expect("write");
    }

    fn counts(engine: &ReindexEngine, target: &str) -> (usize, usize) {
        let result = engine.backlinks_for(Path::new(target)).expect("backlinks");
        (result.document_count, result.occurrence_count)
    }

    #[test]
    fn test_reindex_engine_workflow() {
        let temp = TempDir::new().expect("tempdir");
        let root = temp.path();

        // 1. Criar arquivos iniciais
        fs::write(root.join("doc1.md"), "# Documento 1\nTag: #onda1").expect("write");
        fs::write(root.join("doc2.md"), "# Documento 2\nVeja [[doc1]]").expect("write");

        let engine = ReindexEngine::new(root.to_path_buf());

        // 2. Full reindex
        let report = engine.full_reindex().expect("full_reindex");
        assert_eq!(report.indexed, 2);
        assert_eq!(report.errors.len(), 0);

        {
            let index = engine.index.lock().unwrap();
            assert_eq!(index.len(), 2);
            assert!(index.contains(&PathBuf::from("doc1.md")));
            assert!(index.contains(&PathBuf::from("doc2.md")));
        }

        // 3. Modificar/Adicionar novo arquivo incrementalmente
        fs::write(root.join("doc3.md"), "# Documento 3\n#rust").expect("write");
        engine.reindex_file(&PathBuf::from("doc3.md")).expect("reindex doc3");

        {
            let index = engine.index.lock().unwrap();
            assert_eq!(index.len(), 3);
            let d3 = index.get(&PathBuf::from("doc3.md")).expect("doc3");
            assert_eq!(d3.title, Some("Documento 3".to_string()));
            assert!(d3.tags.contains(&"rust".to_string()));
        }

        // 4. Remover arquivo do índice
        let removed = engine.remove_file(&PathBuf::from("doc2.md")).expect("remove");
        assert!(removed);

        {
            let index = engine.index.lock().unwrap();
            assert_eq!(index.len(), 2);
            assert!(!index.contains(&PathBuf::from("doc2.md")));
        }
    }

    #[test]
    fn add_and_remove_link_via_reindex_file_updates_backlinks() {
        let temp = TempDir::new().expect("tempdir");
        let root = temp.path();
        write(root, "a.md", "# A\n");
        write(root, "src.md", "# Src\n");
        let engine = ReindexEngine::new(root.to_path_buf());
        engine.full_reindex().expect("full");
        assert_eq!(counts(&engine, "a.md"), (0, 0));

        write(root, "src.md", "# Src\nSee [[a]]\nAlso [[a]]\n");
        engine.reindex_file(Path::new("src.md")).expect("add links");
        assert_eq!(counts(&engine, "a.md"), (1, 2));

        write(root, "src.md", "# Src\n");
        engine.reindex_file(Path::new("src.md")).expect("remove links");
        assert_eq!(counts(&engine, "a.md"), (0, 0));
    }

    #[test]
    fn retarget_a_to_b_and_multi_save_does_not_duplicate() {
        let temp = TempDir::new().expect("tempdir");
        let root = temp.path();
        write(root, "a.md", "# A\n");
        write(root, "b.md", "# B\n");
        write(root, "src.md", "[[a]]\n");
        let engine = ReindexEngine::new(root.to_path_buf());
        engine.full_reindex().expect("full");
        assert_eq!(counts(&engine, "a.md"), (1, 1));

        write(root, "src.md", "[[b]]\n");
        engine.reindex_file(Path::new("src.md")).expect("retarget");
        engine.reindex_file(Path::new("src.md")).expect("retarget again");
        engine.reindex_file(Path::new("src.md")).expect("retarget again");
        assert_eq!(counts(&engine, "a.md"), (0, 0));
        assert_eq!(counts(&engine, "b.md"), (1, 1));
    }

    #[test]
    fn creating_unresolved_target_then_reindex_establishes_relation() {
        let temp = TempDir::new().expect("tempdir");
        let root = temp.path();
        write(root, "src.md", "[[nova-nota]]\n");
        let engine = ReindexEngine::new(root.to_path_buf());
        engine.full_reindex().expect("full");
        assert_eq!(counts(&engine, "nova-nota.md"), (0, 0));

        write(root, "nova-nota.md", "# Nova nota\n");
        engine.reindex_file(Path::new("nova-nota.md")).expect("create target");
        assert_eq!(counts(&engine, "nova-nota.md"), (1, 1));
    }

    #[test]
    fn external_delete_and_watch_apply_remove_backlinks() {
        let temp = TempDir::new().expect("tempdir");
        let root = temp.path();
        write(root, "target.md", "# Target\n");
        write(root, "gone.md", "[[target]]\n");
        let engine = ReindexEngine::new(root.to_path_buf());
        engine.full_reindex().expect("full");
        assert_eq!(counts(&engine, "target.md"), (1, 1));

        engine.apply_external_change("removed", Path::new("gone.md"), None);
        assert_eq!(counts(&engine, "target.md"), (0, 0));
    }

    #[test]
    fn rebuild_matches_incremental_and_loaded_snapshot() {
        let temp = TempDir::new().expect("tempdir");
        let root = temp.path();
        write(root, "a.md", "# A\n");
        write(root, "b.md", "[[a]]\n");
        write(root, "c.md", "[[a]]\n");

        let rebuilt = ReindexEngine::new(root.to_path_buf());
        rebuilt.full_reindex().expect("full");

        let incremental = ReindexEngine::new(root.to_path_buf());
        incremental.reindex_file(Path::new("a.md")).expect("a");
        incremental.reindex_file(Path::new("b.md")).expect("b");
        incremental.reindex_file(Path::new("c.md")).expect("c");

        assert_eq!(counts(&rebuilt, "a.md"), counts(&incremental, "a.md"));
        assert_eq!(counts(&rebuilt, "a.md"), (2, 2));

        let loaded = ReindexEngine::with_index(
            root.to_path_buf(),
            Arc::new(Mutex::new(rebuilt.index.lock().unwrap().clone())),
        );
        loaded.rebuild_backlinks();
        assert_eq!(counts(&loaded, "a.md"), (2, 2));
    }
}

use crate::contracts::{DocumentSnapshot, FileEntry, SearchResult, WorkspaceDescriptor};
use crate::persistence::{atomic_save, atomic_write_bytes, content_hash, read_file};
use crate::workspace::WorkspaceError;
use crate::AppState;
use serde::Deserialize;
use std::fs;
use std::path::PathBuf;
use tauri::State;
use walkdir::WalkDir;

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SaveDocumentRequest {
    pub workspace_id: String,
    pub relative_path: String,
    pub expected_hash: String,
    pub content: String,
}

pub mod metadata;

fn map_ws_err(e: WorkspaceError) -> String {
    e.to_string()
}

#[tauri::command]
pub fn open_workspace(path: String, state: State<'_, AppState>) -> Result<WorkspaceDescriptor, String> {
    let mut reg = state.workspaces.lock();
    let ws = reg
        .open(PathBuf::from(path).as_path())
        .map_err(map_ws_err)?;
    // Drop previous workspaces so only the active root is retained.
    reg.retain(&ws.id);

    // Inicializar ou carregar índice de metadados do workspace
    let engine = md_studio_core::index::ReindexEngine::new(ws.root.clone());
    if let Ok(Some(persisted)) = md_studio_core::index::load_index(&ws.root) {
        if let Ok(mut idx) = engine.index.lock() {
            *idx = persisted;
        }
        engine.rebuild_backlinks();
    } else {
        let _ = engine.full_reindex();
        if let Ok(idx) = engine.index.lock() {
            let _ = md_studio_core::index::save_index(&idx, &ws.root);
        }
    }
    *state.metadata_engine.lock() = Some(engine);

    Ok(WorkspaceDescriptor {
        id: ws.id,
        root_label: ws.root.display().to_string(),
        kind: ws.kind,
    })
}

#[tauri::command]
pub fn list_entries(
    workspace_id: String,
    relative_path: String,
    state: State<'_, AppState>,
) -> Result<Vec<FileEntry>, String> {
    let reg = state.workspaces.lock();
    let dir = reg
        .resolve(&workspace_id, &relative_path)
        .map_err(map_ws_err)?;
    if !dir.is_dir() {
        return Ok(vec![]);
    }
    let mut out = vec![];
    for ent in fs::read_dir(&dir).map_err(|e| e.to_string())? {
        let ent = ent.map_err(|e| e.to_string())?;
        let meta = ent.metadata().map_err(|e| e.to_string())?;
        let name = ent.file_name().to_string_lossy().to_string();
        let rel = if relative_path.is_empty() {
            name.clone()
        } else {
            format!("{relative_path}/{name}")
        };
        out.push(FileEntry {
            name,
            relative_path: rel,
            kind: if meta.is_dir() {
                "dir".into()
            } else {
                "file".into()
            },
            size: if meta.is_file() { Some(meta.len()) } else { None },
        });
    }
    out.sort_by(|a, b| a.name.cmp(&b.name));
    Ok(out)
}

#[tauri::command]
pub fn read_document(
    workspace_id: String,
    path: String,
    state: State<'_, AppState>,
) -> Result<DocumentSnapshot, String> {
    let reg = state.workspaces.lock();
    let full = reg.resolve(&workspace_id, &path).map_err(map_ws_err)?;
    let (content, hash, mtime) = read_file(&full).map_err(|e| e.to_string())?;
    Ok(DocumentSnapshot {
        workspace_id,
        relative_path: path,
        content,
        encoding: "utf-8".into(),
        mtime_ms: mtime,
        content_hash: hash,
        version: 1,
    })
}

#[tauri::command]
pub fn save_document(
    req: SaveDocumentRequest,
    state: State<'_, AppState>,
) -> Result<serde_json::Value, String> {
    let reg = state.workspaces.lock();
    let full = reg
        .resolve(&req.workspace_id, &req.relative_path)
        .map_err(map_ws_err)?;
    match atomic_save(&full, &req.expected_hash, &req.content) {
        Ok(hash) => {
            // Reindexar arquivo salvo de forma resiliente (falha de índice não bloqueia save)
            if let Some(engine) = state.metadata_engine.lock().as_ref().cloned() {
                let _ = engine.reindex_file(&full);
                if let Ok(idx) = engine.index.lock() {
                    let _ = md_studio_core::index::save_index(&idx, &engine.root);
                }
            }

            let snap = DocumentSnapshot {
                workspace_id: req.workspace_id,
                relative_path: req.relative_path,
                content: req.content,
                encoding: "utf-8".into(),
                mtime_ms: 0,
                content_hash: hash,
                version: 2,
            };
            Ok(serde_json::json!({ "ok": true, "snapshot": snap }))
        }
        Err(crate::persistence::SaveError::HashMismatch) => Ok(serde_json::json!({
            "ok": false,
            "code": "HashMismatch",
            "message": "Arquivo alterado no disco"
        })),
        Err(e) => Ok(serde_json::json!({
            "ok": false,
            "code": "IoError",
            "message": e.to_string()
        })),
    }
}

#[tauri::command]
pub fn search_workspace(
    workspace_id: String,
    query: String,
    state: State<'_, AppState>,
) -> Result<Vec<SearchResult>, String> {
    if query.trim().is_empty() {
        return Ok(vec![]);
    }
    let reg = state.workspaces.lock();
    let ws = reg.get(&workspace_id).ok_or_else(|| "not found".to_string())?;
    let mut out = vec![];
    for entry in WalkDir::new(&ws.root).into_iter().filter_map(|e| e.ok()) {
        if !entry.file_type().is_file() {
            continue;
        }
        let path = entry.path();
        if path.extension().and_then(|s| s.to_str()) != Some("md") {
            continue;
        }
        let Ok(text) = fs::read_to_string(path) else { continue };
        for (i, line) in text.lines().enumerate() {
            if line.contains(&query) {
                let rel = path
                    .strip_prefix(&ws.root)
                    .unwrap_or(path)
                    .to_string_lossy()
                    .to_string();
                out.push(SearchResult {
                    relative_path: rel,
                    line: (i + 1) as u32,
                    preview: line.chars().take(200).collect(),
                });
                if out.len() >= 200 {
                    return Ok(out);
                }
            }
        }
    }
    let _ = content_hash(query.as_bytes());
    Ok(out)
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ExportHtmlRequest {
    /// Pre-rendered, sanitized HTML document from the frontend preview pipeline.
    pub html: String,
    pub destination: String,
    /// When false, refuse to clobber an existing file (FE must confirm overwrite).
    pub overwrite: bool,
}

#[tauri::command]
pub fn export_html(req: ExportHtmlRequest) -> Result<(), String> {
    let dest = PathBuf::from(&req.destination);
    if !dest.is_absolute() {
        return Err("destination must be an absolute path".into());
    }
    if dest.exists() && !req.overwrite {
        return Err("ExportTargetExists".into());
    }
    atomic_write_bytes(&dest, req.html.as_bytes()).map_err(|e| e.to_string())?;
    Ok(())
}

#[cfg(test)]
mod export_tests {
    use super::*;
    use std::fs;
    use tempfile::tempdir;

    #[test]
    fn export_writes_rendered_html_not_pre_stub() {
        let dir = tempdir().unwrap();
        let dest = dir.path().join("out.html");
        let html = "<!DOCTYPE html><html><body><h1>Title</h1><p>Hi</p></body></html>".to_string();
        export_html(ExportHtmlRequest {
            html: html.clone(),
            destination: dest.to_string_lossy().to_string(),
            overwrite: false,
        })
        .unwrap();
        let got = fs::read_to_string(&dest).unwrap();
        assert!(got.contains("<h1>Title</h1>"));
        assert!(!got.contains("<pre>"));
    }

    #[test]
    fn export_refuses_overwrite_without_flag() {
        let dir = tempdir().unwrap();
        let dest = dir.path().join("out.html");
        fs::write(&dest, "old").unwrap();
        let err = export_html(ExportHtmlRequest {
            html: "<html></html>".into(),
            destination: dest.to_string_lossy().to_string(),
            overwrite: false,
        })
        .unwrap_err();
        assert_eq!(err, "ExportTargetExists");
    }

    #[test]
    fn export_overwrite_when_allowed() {
        let dir = tempdir().unwrap();
        let dest = dir.path().join("out.html");
        fs::write(&dest, "old").unwrap();
        export_html(ExportHtmlRequest {
            html: "<html><body>new</body></html>".into(),
            destination: dest.to_string_lossy().to_string(),
            overwrite: true,
        })
        .unwrap();
        assert!(fs::read_to_string(&dest).unwrap().contains("new"));
    }
}

/// Return (and clear) the Markdown path passed on process argv at cold start, if any.
#[tauri::command]
pub fn get_launch_path(state: State<'_, AppState>) -> Option<String> {
    state.launch_path.lock().take()
}

#[tauri::command]
pub async fn close_splash(app: tauri::AppHandle) -> Result<(), String> {
    use tauri::Manager;
    if let Some(splash) = app.get_webview_window("splashscreen") {
        let _ = splash.close();
    }
    if let Some(main) = app.get_webview_window("main") {
        let _ = main.show();
        let _ = main.set_focus();
    }
    Ok(())
}

//! Real filesystem watcher (notify) with debounce and path fence.
//! Emits `workspace://change` Tauri events. Never mutates documents.

use notify::{Event, EventKind, RecommendedWatcher, RecursiveMode, Watcher};
use notify::event::{ModifyKind, RenameMode};
use parking_lot::Mutex;
use serde::Serialize;
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::mpsc;
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};
use tauri::{AppHandle, Emitter, Manager, State};

use crate::AppState;

pub const WATCH_EVENT: &str = "workspace://change";
const DEBOUNCE: Duration = Duration::from_millis(300);

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct WatchEventDto {
    /// created | modified | removed | renamed
    pub r#type: String,
    pub relative_path: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub from: Option<String>,
    pub workspace_id: String,
}

struct ActiveWatch {
    workspace_id: String,
    root: PathBuf,
    stop: Arc<AtomicBool>,
}

#[derive(Default)]
pub struct WatcherHub {
    active: Mutex<Option<ActiveWatch>>,
}

impl WatcherHub {
    pub fn stop(&self) {
        if let Some(a) = self.active.lock().take() {
            a.stop.store(true, Ordering::SeqCst);
        }
    }
}

fn relativize(root: &Path, full: &Path) -> Option<String> {
    let root_c = root.canonicalize().ok()?;
    let full_c = if full.exists() {
        full.canonicalize().ok()?
    } else {
        // deleted path: canonicalize parent + join name
        let parent = full.parent()?.canonicalize().ok()?;
        parent.join(full.file_name()?)
    };
    let rel = full_c.strip_prefix(&root_c).ok()?;
    let s = rel.to_string_lossy().replace('\\', "/");
    if s.is_empty() || s.contains("..") {
        return None;
    }
    Some(s)
}

fn kind_label(kind: &EventKind) -> Option<&'static str> {
    match kind {
        EventKind::Create(_) => Some("created"),
        EventKind::Modify(ModifyKind::Name(RenameMode::To)) => Some("renamed"),
        EventKind::Modify(ModifyKind::Name(RenameMode::From)) => Some("renamed"),
        EventKind::Modify(ModifyKind::Name(RenameMode::Both)) => Some("renamed"),
        EventKind::Modify(_) => Some("modified"),
        EventKind::Remove(_) => Some("removed"),
        _ => None,
    }
}

fn spawn_watcher(
    app: AppHandle,
    workspace_id: String,
    root: PathBuf,
    stop: Arc<AtomicBool>,
) -> Result<(), String> {
    let (tx, rx) = mpsc::channel::<Event>();
    let mut watcher = RecommendedWatcher::new(
        move |res: Result<Event, notify::Error>| {
            if let Ok(ev) = res {
                let _ = tx.send(ev);
            }
        },
        notify::Config::default(),
    )
    .map_err(|e| e.to_string())?;

    watcher
        .watch(&root, RecursiveMode::Recursive)
        .map_err(|e| e.to_string())?;

    thread::Builder::new()
        .name("md-studio-watcher".into())
        .spawn(move || {
            // Keep watcher alive in this thread.
            let _watcher = watcher;
            let mut pending: HashMap<String, WatchEventDto> = HashMap::new();
            let mut last_push = Instant::now();

            loop {
                if stop.load(Ordering::SeqCst) {
                    break;
                }
                match rx.recv_timeout(Duration::from_millis(50)) {
                    Ok(event) => {
                        let Some(label) = kind_label(&event.kind) else { continue };
                        let paths = event.paths;
                        if paths.is_empty() {
                            continue;
                        }
                        if label == "renamed" && paths.len() >= 2 {
                            let from = relativize(&root, &paths[0]);
                            let to = relativize(&root, &paths[1]);
                            if let (Some(from), Some(to)) = (from, to) {
                                pending.insert(
                                    to.clone(),
                                    WatchEventDto {
                                        r#type: "renamed".into(),
                                        relative_path: to,
                                        from: Some(from),
                                        workspace_id: workspace_id.clone(),
                                    },
                                );
                            }
                        } else {
                            for p in paths {
                                if let Some(rel) = relativize(&root, &p) {
                                    pending.insert(
                                        rel.clone(),
                                        WatchEventDto {
                                            r#type: label.into(),
                                            relative_path: rel,
                                            from: None,
                                            workspace_id: workspace_id.clone(),
                                        },
                                    );
                                }
                            }
                        }
                    }
                    Err(mpsc::RecvTimeoutError::Timeout) => {}
                    Err(mpsc::RecvTimeoutError::Disconnected) => break,
                }

                if !pending.is_empty() && last_push.elapsed() >= DEBOUNCE {
                    let batch: Vec<_> = pending.drain().map(|(_, v)| v).collect();
                    last_push = Instant::now();
                    for dto in batch {
                        apply_watch_to_engine(&app, &dto);
                        let _ = app.emit(WATCH_EVENT, dto);
                    }
                }
            }

            // flush remaining
            for (_, dto) in pending.drain() {
                apply_watch_to_engine(&app, &dto);
                let _ = app.emit(WATCH_EVENT, dto);
            }
        })
        .map_err(|e| e.to_string())?;

    Ok(())
}

fn apply_watch_to_engine(app: &AppHandle, dto: &WatchEventDto) {
    let Some(state) = app.try_state::<crate::AppState>() else {
        return;
    };
    let engine = state.metadata_engine.lock().as_ref().cloned();
    let Some(engine) = engine else {
        return;
    };
    engine.apply_external_change(
        &dto.r#type,
        Path::new(&dto.relative_path),
        dto.from.as_deref().map(Path::new),
    );
}

#[tauri::command]
pub fn start_watching(
    workspace_id: String,
    app: AppHandle,
    state: State<'_, AppState>,
) -> Result<(), String> {
    let root = {
        let reg = state.workspaces.lock();
        let ws = reg
            .get(&workspace_id)
            .ok_or_else(|| "workspace not found".to_string())?;
        ws.root.clone()
    };

    // Replace any previous watch.
    state.watcher.stop();
    let stop = Arc::new(AtomicBool::new(false));
    spawn_watcher(app, workspace_id.clone(), root.clone(), stop.clone())?;
    *state.watcher.active.lock() = Some(ActiveWatch {
        workspace_id,
        root,
        stop,
    });
    Ok(())
}

#[tauri::command]
pub fn stop_watching(state: State<'_, AppState>) -> Result<(), String> {
    state.watcher.stop();
    Ok(())
}

/// Pure helpers for unit tests (path fence + debounce coalescing key).
pub fn fence_relative(root: &Path, candidate: &Path) -> Option<String> {
    relativize(root, candidate)
}

pub fn coalesce_key(ev: &WatchEventDto) -> String {
    format!("{}:{}", ev.r#type, ev.relative_path)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use tempfile::tempdir;

    #[test]
    fn fence_rejects_outside() {
        let dir = tempdir().unwrap();
        let inside = dir.path().join("a.md");
        fs::write(&inside, "x").unwrap();
        let outside = dir.path().parent().unwrap().join("escape.md");
        assert!(fence_relative(dir.path(), &inside).is_some());
        // outside path should not strip_prefix successfully
        assert!(fence_relative(dir.path(), &outside).is_none());
    }

    #[test]
    fn fence_normalizes_relative() {
        let dir = tempdir().unwrap();
        let nested = dir.path().join("docs");
        fs::create_dir_all(&nested).unwrap();
        let f = nested.join("readme.md");
        fs::write(&f, "hi").unwrap();
        let rel = fence_relative(dir.path(), &f).unwrap();
        assert_eq!(rel, "docs/readme.md");
    }

    #[test]
    fn coalesce_key_stable() {
        let ev = WatchEventDto {
            r#type: "modified".into(),
            relative_path: "a.md".into(),
            from: None,
            workspace_id: "w".into(),
        };
        assert_eq!(coalesce_key(&ev), "modified:a.md");
    }
}
